import java.util.*;
public class AgendaTelefonica {
    public static void main(String[] args) {
        Map<String, String> agenda = new TreeMap<>();
        agenda.put("Ana", "555-0101");
        agenda.put("Carlos", "555-0202");
        agenda.put("Beatriz", "555-0303");

        System.out.println("Carlos' phone: " + agenda.get("Carlos"));
        System.out.println("\nAll contacts:");
        for (Map.Entry<String, String> e : agenda.entrySet()) {
            System.out.println(e.getKey() + " -> " + e.getValue());
        }
    }
}
